#!/usr/bin/env -S uv run --script
# Synced from bootstrap: repo/tools/kotlin/tasks/code-lint-detekt.py. Do not edit this file.
# The next sync writes it again, and each change in this file is lost.
# /// script
# requires-python = ">=3.14"
# dependencies = []
# ///
# MISE description="Lint the Kotlin files with detekt"
# MISE hide=true
# MISE tools={uv="latest", python="3.14"}
# USAGE flag "--all" help="lint every file of the repository, not only the uncommitted files"
# USAGE flag "--debug" help="emit debug logs"
# USAGE flag "--fix" help="accepted for the code:lint contract; ktlint decides the layout"
# USAGE arg "[files]" var=#true help="the files to lint; only the .kt and .kts files are used; the default is the uncommitted files"
# FILES include="*.kt *.kts" exclude="**/generated/**"

import os
import re
import subprocess
import sys
import tempfile

sys.dont_write_bytecode = True
sys.path.insert(0, f"{os.environ['MISE_PROJECT_ROOT']}/.config/mise/tasks/_scripts")
import helpers  # noqa: E402

# The whitespace characters of [[:space:]] in the shell.
SPACE = re.compile(r"[ \t\n\r\f\v]")


def flag(name):
  """Whether mise gives the flag name as true."""
  return os.environ.get(f"usage_{name}", "false") == "true"


def exit_code(code):
  """The exit code of the shell for a return code of subprocess."""
  return code if code >= 0 else 128 - code


def main():
  # Shipped with the kotlin tool. Without detekt, the task does not apply and
  # prints nothing.
  if not helpers.has_tool("detekt-cli"):
    sys.exit(0)
  os.chdir(os.environ["MISE_PROJECT_ROOT"])

  # code:lint passes its flags and files to each code:lint:* task. The list
  # comes from gate_files (the # FILES header above). An empty list: nothing
  # to do.
  args = [f"--{name}" for name in ("all", "debug", "fix") if flag(name)]
  listing = helpers.gate_files(__file__, *args, *helpers.usage_files())
  argfile = None
  try:
    if os.path.getsize(listing) == 0:
      sys.exit(0)

    helpers.print_header("Linting the Kotlin files with detekt ...")

    # --input takes one list: separated by commas in detekt 1.x, and by the
    # path separator in 2.x. The argument file below separates on whitespace.
    # Thus a path with the separator or with whitespace is skipped.
    separator = ","
    result = helpers.tool("detekt-cli", "--version", stdout=subprocess.PIPE, stderr=subprocess.DEVNULL)
    version = os.fsdecode(result.stdout) if result.returncode == 0 else ""
    if re.match(r"[2-9]", version):
      separator = ":"
    inputs = []
    with open(listing, encoding="utf-8", errors="surrogateescape") as lines:
      for file in lines.read().splitlines():
        if separator in file or SPACE.search(file):
          helpers.print_warn(f"detekt cannot read the path {file}, skipped")
          continue
        inputs.append(file)
    if not inputs:
      sys.exit(0)

    # An argument file, not the command line: Linux limits one argument to
    # 128 KiB, and the --input list of a large tree can be longer.
    fd, argfile = tempfile.mkstemp(prefix="code-lint-detekt.", dir=os.environ.get("TMPDIR") or "/tmp")
    lines = ["--input", separator.join(inputs), "--config", ".config/detekt.yml", "--build-upon-default-config"]
    if flag("debug"):
      lines.append("--debug")
    with os.fdopen(fd, "w", encoding="utf-8", errors="surrogateescape") as out:
      out.write("".join(f"{line}\n" for line in lines))
    result = helpers.tool("detekt-cli", f"@{argfile}")
    sys.exit(exit_code(result.returncode))
  finally:
    if argfile:
      os.remove(argfile)
    os.remove(listing)


main()
